-- Rename columns without losing data (snake_case)
ALTER TABLE "area" RENAME COLUMN "parentId" TO "parent_id";
ALTER TABLE "area" RENAME COLUMN "createdAt" TO "created_at";

-- UUID v7 generated by PostgreSQL 18
ALTER TABLE "area" ALTER COLUMN "id" SET DEFAULT uuidv7();

-- Soft-delete flag
ALTER TABLE "area" ADD COLUMN "active" BOOLEAN NOT NULL DEFAULT true;

-- Align timestamp precision with docs/03 (6 -> 3)
ALTER TABLE "area" ALTER COLUMN "created_at" TYPE TIMESTAMPTZ(3);

-- Parent deletion must be blocked while children exist
ALTER TABLE "area" DROP CONSTRAINT "area_parentId_fkey";
ALTER TABLE "area" ADD CONSTRAINT "area_parent_id_fkey"
  FOREIGN KEY ("parent_id") REFERENCES "area"("id")
  ON DELETE RESTRICT ON UPDATE CASCADE;
